import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String a = sc.next();
        sc.close();

        // Precompute factorials for digits 0-9
        int[] fact = new int[10];
        fact[0] = 1;
        for (int i = 1; i < 10; i++) {
            fact[i] = fact[i - 1] * i;
        }

        // Compute the product of factorials of digits in a
        int product = 1;
        for (int i = 0; i < n; i++) {
            int d = a.charAt(i) - '0';
            product *= fact[d];
        }

        // Decompose the product into digits 2-9 in descending order
        List<Integer> digits = new ArrayList<>();
        for (int d = 9; d >= 2; d--) {
            while (product % fact[d] == 0) {
                digits.add(d);
                product /= fact[d];
            }
        }

        // Build the result string
        StringBuilder sb = new StringBuilder();
        for (int d : digits) {
            sb.append(d);
        }
        System.out.println(sb.toString());
    }
}
